DECK.register('s02-nothing', `
<header>
  <h1 style="font-size:52px; max-width:28ch;">Both are balanced presentations<br>of the trivial group</h1>
  <div class="kicker">X = x⁻¹ · Y = y⁻¹</div>
</header>
<div class="viz">
<svg viewBox="0 0 1600 760" preserveAspectRatio="xMidYMid meet" font-family="Figtree" fill="#191813">
  <rect x="70" y="88" width="700" height="500" fill="#FFFFFF" stroke="#191813" stroke-opacity="0.15" stroke-width="1"/>
  <rect x="830" y="88" width="700" height="500" fill="#FFFFFF" stroke="#191813" stroke-opacity="0.15" stroke-width="1"/>

  <text x="420" y="318" text-anchor="middle" font-family="Figtree" font-weight="600" font-size="46" letter-spacing="0.02em">⟨ x, y | x, y ⟩</text>
  <text x="420" y="478" text-anchor="middle" font-family="'IBM Plex Mono', monospace" font-weight="400" font-size="24" fill="#191813" fill-opacity="0.6">the trivial presentation · obviously trivial</text>

  <text x="1180" y="318" text-anchor="middle" font-family="Figtree" font-weight="600" font-size="42" letter-spacing="0.02em">⟨ x, y | YYXyx, Yx ⟩</text>
  <text x="1180" y="478" text-anchor="middle" font-family="'IBM Plex Mono', monospace" font-weight="400" font-size="24" fill="#191813" fill-opacity="0.6">the trivial group · provably</text>
</svg>
</div>
`);

